import java.util.Map;
import java.util.UUID;
import java.time.Instant;
import java.sql.Timestamp;
import java.nio.charset.StandardCharsets;
import org.springframework.context.annotation.Profile;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.jdbc.core.namedparam.MapSqlParameterSource;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
@Service @Profile("db")
public final class JdbcExchanges implements Exchanges {
 private final NamedParameterJdbcTemplate jdbc;private final OrderQueries queries;private final OrderConfirmations confirmations;private final ExchangeApplications applications;private final ExchangeOffers offers;private final ExchangeReservations stocks;private final Outbox outbox;private final TransactionTemplate tx;private final com.example.marketplace.order.api.PhysicalOrders physical;private final java.time.Clock clock;
 private final tools.jackson.databind.ObjectMapper mapper=new tools.jackson.databind.ObjectMapper();
 @org.springframework.beans.factory.annotation.Autowired public JdbcExchanges(NamedParameterJdbcTemplate jdbc,OrderQueries queries,OrderConfirmations confirmations,ExchangeApplications applications,ExchangeOffers offers,ExchangeReservations stocks,Outbox outbox,PlatformTransactionManager manager,com.example.marketplace.order.api.PhysicalOrders physical) { this(jdbc,queries,confirmations,applications,offers,stocks,outbox,manager,physical,null); }
 public JdbcExchanges(NamedParameterJdbcTemplate jdbc,OrderQueries queries,OrderConfirmations confirmations,ExchangeApplications applications,ExchangeOffers offers,ExchangeReservations stocks,Outbox outbox,PlatformTransactionManager manager,com.example.marketplace.order.api.PhysicalOrders physical,java.time.Clock clock) { this.jdbc=jdbc;this.queries=queries;this.confirmations=confirmations;this.applications=applications;this.offers=offers;this.stocks=stocks;this.outbox=outbox;this.tx=new TransactionTemplate(manager);this.physical=physical;this.clock=clock; }
 private Instant now(UUID id) { return clock==null?ExchangeTimeObservation.read(jdbc,"APPROVAL",id):clock.instant().truncatedTo(java.time.temporal.ChronoUnit.MICROS); }
 com.example.marketplace.platform.api.Outbox outbox() { return outbox; }
 @Override public Receipt request(String number,OrderQueries.Authority authority,Request command) {
  if(command==null) { throw new OrderRejected(400); }validate(command.key(),command.expectedRevision(),command.reason());List<Unit> units;try { units=ExchangeRules.canonical(command.units()); }catch(IllegalArgumentException invalid) { throw new OrderRejected(400); }String reason=command.reason().strip();
  return tx.execute(t->{
   var own=queries.lockOwned(number,authority);String hash=hash(own.id()+"|"+command.expectedRevision()+"|"+units+"|"+reason);
   var prior=jdbc.queryForList("SELECT request_fingerprint,receipt::text FROM marketplace.claim_exchange_request WHERE order_id=:order AND request_key=:key FOR UPDATE",Map.of("order",own.id(),"key",command.key()));
   if(!prior.isEmpty()) { if(prior.size()!=1||!hash.equals(prior.getFirst().get("request_fingerprint"))) { throw new OrderRejected(409); }queries.lockOwned(number,authority);return mapper.readValue(prior.getFirst().get("receipt").toString(),Receipt.class); }
   if(!own.state().equals("PAID")||confirmations.get(number,authority).revision()!=command.expectedRevision()) { throw new OrderRejected(409); }
   UUID id=UUID.randomUUID(),hold=UUID.randomUUID(),cause=UUID.randomUUID();var source=applications.begin(number,authority,id,hold,cause,units.stream().map(u->new OrderConfirmations.Unit(u.itemId(),u.ordinal())).toList());
   for(var u:units) { var original=source.units().stream().filter(s->s.itemId().equals(u.itemId())&&s.ordinal()==u.ordinal()).findFirst().orElseThrow(()->new OrderRejected(409));if(!ExchangeRules.samePrice(Long.parseLong(original.originalUnitPrice()),Long.parseLong(offers.existingPublished(source.storeId(),u.targetSkuId()).price()))) { throw new OrderRejected(409); } }
   var receipt=new Receipt(id,hold,"REQUESTED",0,source.orderRevision(),source.requestedAt(),reason,units);
   var p=new MapSqlParameterSource("id",id).addValue("order",own.id()).addValue("seller",source.sellerOrderId()).addValue("hold",hold).addValue("cause",cause).addValue("key",command.key()).addValue("hash",hash).addValue("reason",reason).addValue("at",Timestamp.from(source.requestedAt())).addValue("receipt",mapper.writeValueAsString(receipt)).addValue("source",mapper.writeValueAsString(source));
   jdbc.update("INSERT INTO marketplace.claim_exchange_request(id,order_id,seller_order_id,hold_id,cause_id,request_key,request_fingerprint,reason,state,requested_at,receipt,source_snapshot) VALUES(:id,:order,:seller,:hold,:cause,:key,:hash,:reason,'REQUESTED',:at,CAST(:receipt AS jsonb),CAST(:source AS jsonb))",p);
   for(var u:units) { var physical=source.units().stream().filter(s->s.itemId().equals(u.itemId())&&s.ordinal()==u.ordinal()).findFirst().orElseThrow();jdbc.update("INSERT INTO marketplace.claim_exchange_unit(exchange_id,hold_id,item_id,ordinal,physical_id,target_sku_id,claimed_responsibility) VALUES(:id,:hold,:item,:ordinal,:physical,:sku,:responsibility)",p.addValue("item",u.itemId()).addValue("ordinal",u.ordinal()).addValue("physical",physical.physicalId()).addValue("sku",u.targetSkuId()).addValue("responsibility",u.responsibility().name())); }
   history(id,"REQUESTED",0,reason,authority,source.requestedAt());event(id,"requested",source.requestedAt());queries.lockOwned(number,authority);return receipt;
  });
 }
 @Override public Progress approve(UUID id,OrderQueries.Authority authority,Command command) {
  if(command==null||id==null) { throw new OrderRejected(400); }validate(command.key(),command.expectedRevision(),command.reason());String reason=command.reason().strip();var hint=source(id);queries.sellerOrder(hint.sellerOrderId(),authority);
  return tx.execute(t->{
   jdbc.query("SELECT pg_advisory_xact_lock(hashtextextended(:key,0))",Map.of("key","claim/exchange/approve/"+id+"/"+command.key()),(r,n)->r.getObject(1));String fingerprint=hash("APPROVED|"+command.expectedRevision()+"|"+reason);var old=jdbc.queryForList("SELECT fingerprint,receipt::text FROM marketplace.claim_exchange_command WHERE exchange_id=:id AND command_key=:key",Map.of("id",id,"key",command.key()));
   if(!old.isEmpty()) { applications.lockSeller(authority,id);lock(id);if(!fingerprint.equals(old.getFirst().get("fingerprint"))) { throw new OrderRejected(409); }applications.lockSeller(authority,id);return mapper.readValue(old.getFirst().get("receipt").toString(),Progress.class); }
   var wanted=receipt(id).units().stream().map(Unit::targetSkuId).toList();var eligibility=offers.lockExistingForSeller(authority.member(),hint.storeId(),wanted);var lockedOffers=eligibility.offers();var actual=applications.lockSeller(authority,id);var row=lock(id);requireTradeTargets(id,eligibility);int previousSequence=((Number)row.get("current_sequence")).intValue();boolean initial=previousSequence==0&&List.of("REQUESTED","RESPONSIBILITY_PENDING","COLLECTING","READY","REVIEW_REQUIRED").contains(row.get("state").toString());
   if(((Number)row.get("version")).longValue()!=command.expectedRevision()||!initial&&!List.of("EXPIRED","REVIEW_REQUIRED").contains(row.get("state").toString())||initial&&previousSequence!=0||!initial&&previousSequence<1) { throw new OrderRejected(409); }
   ExchangeReservations.Released previous=null;if(!initial) { var current=stocks.lockCurrent(id);if(current.stream().anyMatch(r->!r.status().equals("EXPIRED"))) { throw new OrderRejected(409); }previous=stocks.released(id,previousSequence);if(previous.reason()!=ExchangeReservations.ReleaseReason.EXPIRED) { throw new OrderRejected(409); } }
   var accepted=receipt(id);var reservationUnits=new java.util.ArrayList<ExchangeReservations.Unit>();for(var u:accepted.units()) { var original=actual.units().stream().filter(source->source.itemId().equals(u.itemId())&&source.ordinal()==u.ordinal()).findFirst().orElseThrow(()->new OrderRejected(409));var target=lockedOffers.stream().filter(offer->offer.skuId().equals(u.targetSkuId())).findFirst().orElseThrow(()->new OrderRejected(409));if(!ExchangeRules.samePrice(Long.parseLong(original.originalUnitPrice()),Long.parseLong(target.price()))) { throw new OrderRejected(409); }reservationUnits.add(new ExchangeReservations.Unit(original.physicalId(),original.itemId(),original.ordinal(),original.reservationId(),original.skuId(),u.targetSkuId())); }
   applications.lockSeller(authority,id);var at=now(id);var expires=ExchangeRules.expires(at);int sequence=Math.incrementExact(previousSequence);long revision=Math.incrementExact(command.expectedRevision());var reserved=stocks.reserve(new ExchangeReservations.Request(id,actual.orderId(),actual.sellerOrderId(),actual.units().getFirst().checkoutId(),sequence,at,expires,reservationUnits));var fixed=physical.application(id);stocks.bindSources(id,reserved.stream().map(r->{var source=fixed.stream().filter(v->v.originalPhysicalId().equals(r.physicalId())).findFirst().orElseThrow(()->new OrderRejected(409));return new ExchangeReservations.PhysicalBinding(r.id(),source.id(),source.stock().id());}).toList());
   var physicalFacts=physical(id);String state=physicalFacts.stream().anyMatch(p->p.collection().equals("LOST_REPORTED"))?"REVIEW_REQUIRED":physicalFacts.stream().allMatch(p->p.collection().equals("RECEIVED")&&p.inspectionId()!=null)?"READY":physicalFacts.stream().anyMatch(p->p.collection().equals("RECEIVED"))?"COLLECTING":"APPROVED";var p=new MapSqlParameterSource("id",id).addValue("at",Timestamp.from(at)).addValue("expires",Timestamp.from(expires)).addValue("offers",mapper.writeValueAsString(lockedOffers)).addValue("seq",sequence).addValue("revision",revision).addValue("state",state);
   jdbc.update("UPDATE marketplace.claim_exchange_request SET state=:state,version=:revision,current_sequence=:seq,approved_at=:at,expires_at=:expires,approved_offers=CAST(:offers AS jsonb) WHERE id=:id",p);history(id,"APPROVED",revision,reason,authority,at);event(id,initial?"approved":"approved-"+sequence,at);var progress=progress(id);String receipt=mapper.writeValueAsString(progress);jdbc.update("INSERT INTO marketplace.claim_exchange_command(exchange_id,command_key,fingerprint,action,version,receipt) VALUES(:id,:key,:hash,'APPROVED',:revision,CAST(:receipt AS jsonb))",p.addValue("key",command.key()).addValue("hash",fingerprint).addValue("receipt",receipt));ExchangeReservationFacts.approval(jdbc,outbox,id,sequence,command.key(),command.expectedRevision(),revision,at,expires,receipt);requireTradeTargets(id,offers.lockExistingForSeller(authority.member(),hint.storeId(),wanted));applications.lockSeller(authority,id);return progress;
  });
 }
 void requireTradeTargets(UUID id,ExchangeOffers.TradeTargets targets) {
  if(targets==null||!source(id).storeId().equals(targets.storeId())){throw new OrderRejected(409);}if(targets.state().equals("OPEN")&&targets.visible()){return;}if(!List.of("SUSPENDED","CLOSED").contains(targets.state())){throw new OrderRejected(409);}var facts=physical(id);if(facts.size()!=receipt(id).units().size()||facts.isEmpty()||facts.stream().anyMatch(p->!p.collection().equals("RECEIVED")||p.inspectionId()==null||p.responsibility()!=Responsibility.SELLER)){throw new OrderRejected(409);}
 }
 @Override public Progress get(String number,UUID id,OrderQueries.Authority authority) { return tx.execute(t->{applications.lockOwner(number,authority,id);lock(id);var p=progress(id);applications.lockOwner(number,authority,id);return p;}); }
 @Override public Page owner(String number,OrderQueries.Authority authority) {
  return tx.execute(t->{var own=queries.lockOwned(number,authority);var detail=queries.detail(number,authority);var ids=jdbc.queryForList("SELECT id FROM marketplace.claim_exchange_request WHERE order_id=:id ORDER BY requested_at,id",Map.of("id",own.id()),UUID.class);var values=ids.stream().map(id->get(number,id,authority)).toList();var choices=new java.util.ArrayList<Choice>();
   var eligibility=confirmations.get(number,authority);var now=jdbc.queryForObject("SELECT clock_timestamp()",Map.of(),Timestamp.class).toInstant();for(var store:detail.stores()) { var targets=offers.existingCandidates(store.storeId(),null,50);for(var item:store.items()) { for(var unit:item.units()) { if(eligibility.units().stream().noneMatch(e->e.unit().itemId().equals(item.id())&&e.unit().ordinal()==unit.ordinal()&&e.lifecycle().equals("OPEN")&&e.deliveredAt()!=null&&e.dueAt()!=null&&now.isBefore(e.dueAt()))) { continue; }choices.add(new Choice(item.id(),unit.ordinal(),item.skuId(),item.title(),item.unitPrice(),targets)); } } }
   queries.lockOwned(number,authority);return new Page(eligibility.revision(),values,choices);
  });
 }
 @Override public Page seller(UUID seller,OrderQueries.Authority authority) { return tx.execute(t->{queries.lockSellerOrder(seller,authority);var ids=jdbc.queryForList("SELECT id FROM marketplace.claim_exchange_request WHERE seller_order_id=:id ORDER BY requested_at,id",Map.of("id",seller),UUID.class);var values=ids.stream().map(id->{var source=applications.lockRecorded(id);if(!seller.equals(source.sellerOrderId())) { throw new OrderRejected(409); }lock(id);return progress(id);}).toList();queries.lockSellerOrder(seller,authority);return new Page(-1,values,List.of());}); }
 Receipt receipt(UUID id) { var rows=jdbc.queryForList("SELECT receipt::text FROM marketplace.claim_exchange_request WHERE id=:id",Map.of("id",id),String.class);if(rows.size()!=1) { throw new OrderRejected(404); }return mapper.readValue(rows.getFirst(),Receipt.class); }
 ExchangeApplications.Source source(UUID id) { var rows=jdbc.queryForList("SELECT source_snapshot::text FROM marketplace.claim_exchange_request WHERE id=:id",Map.of("id",id),String.class);if(rows.size()!=1) { throw new OrderRejected(404); }return mapper.readValue(rows.getFirst(),ExchangeApplications.Source.class); }
 Map<String,Object> lock(UUID id) { var rows=jdbc.queryForList("SELECT * FROM marketplace.claim_exchange_request WHERE id=:id FOR UPDATE",Map.of("id",id));if(rows.size()!=1) { throw new OrderRejected(404); }return rows.getFirst(); }
 Progress progress(UUID id) { var row=lock(id);var history=jdbc.query("SELECT * FROM marketplace.claim_exchange_history WHERE exchange_id=:id ORDER BY version",Map.of("id",id),(r,n)->new History(r.getString("action"),r.getLong("version"),r.getString("reason"),r.getTimestamp("occurred_at").toInstant()));var approved=mapper.readValue(row.get("approved_offers").toString(),new tools.jackson.core.type.TypeReference<List<ExchangeOffers.Offer>>() {});return new Progress(receipt(id),row.get("state").toString(),((Number)row.get("version")).longValue(),history,stocks.get(id),approved,ExchangeRules.POLICY,physical(id)); }
 private List<Physical> physical(UUID id) { var result=new java.util.ArrayList<Physical>();for(var source:physical.application(id)) { var p=Map.of("id",id,"item",source.itemId(),"ordinal",source.ordinal());var received=jdbc.queryForList("SELECT id,status FROM marketplace.claim_exchange_collection WHERE exchange_id=:id AND item_id=:item AND ordinal=:ordinal ORDER BY version DESC LIMIT 1",p);var inspected=jdbc.queryForList("SELECT inspection_id,condition,responsibility,restitution_id FROM marketplace.claim_exchange_inspection_unit WHERE exchange_id=:id AND item_id=:item AND ordinal=:ordinal",p);var c=received.isEmpty()?null:received.getFirst();var i=inspected.isEmpty()?null:inspected.getFirst();result.add(new Physical(source.itemId(),source.ordinal(),source.id(),source.round(),source.stock().skuId(),c==null?"PENDING":c.get("status").toString(),c==null?null:(UUID)c.get("id"),i==null?"NOT_INSPECTED":i.get("condition").toString(),i==null?null:(UUID)i.get("inspection_id"),i==null?null:Responsibility.valueOf(i.get("responsibility").toString()),i==null?null:(UUID)i.get("restitution_id"))); }return List.copyOf(result); }
 void history(UUID id,String action,long version,String reason,OrderQueries.Authority authority,Instant at) { jdbc.update("INSERT INTO marketplace.claim_exchange_history(id,exchange_id,action,version,reason,actor,occurred_at) VALUES(:event,:id,:action,:version,:reason,:actor,:at)",Map.of("event",UUID.randomUUID(),"id",id,"action",action,"version",version,"reason",reason,"actor",authority.member()==null?"GAS":"MEMBER:"+authority.member(),"at",Timestamp.from(at))); }
 void event(UUID id,String action,Instant at) { String key="exchange-"+action+":"+id;outbox.append(new Outbox.Event(UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)),new Jobs.Command("EXCHANGE_RECORDED.v1",key,id.toString(),id.toString(),at))); }
 private static void validate(String key,Long revision,String reason) { if(key==null||!key.matches("[A-Za-z0-9][A-Za-z0-9._:-]{0,99}")||revision==null||revision<0||reason==null||reason.isBlank()||reason.length()>500) { throw new OrderRejected(400); } }
 private static String hash(String s) { try { return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8))); }catch(java.security.NoSuchAlgorithmException impossible) { throw new IllegalStateException(impossible); } }
}
